def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_me, last_opp = history[-1]

    opp_d = opp.count('D')
    my_d = me.count('D')
    opp_c = n - opp_d
    coop_rate = opp_c / n

    remaining = 100 - n

    # Repeated mutual defection: try to restore cooperation once.
    if n >= 3 and last_me == 'D' and last_opp == 'D' and me[-2] == 'D' and opp[-2] == 'D':
        return 'C'

    # Defect in final round.
    if remaining <= 1:
        return 'D'

    # Last few rounds: defect unless opponent is clearly retaliatory and we're currently in mutual C.
    if remaining <= 3:
        if last_opp == 'C' and last_me == 'C':
            return 'D'
        return 'D'

    # Pure / near-pure defector: defect hard.
    if n >= 6 and opp_d >= n - 1:
        return 'D'
    if n >= 12 and opp_d * 4 >= n * 3:
        return 'D'

    # Pure cooperator: cooperate most of the time, but occasionally exploit
    # when we can restore cooperation afterward.
    if opp_d == 0:
        if n >= 8 and n % 6 == 0 and remaining > 5:
            return 'D'
        return 'C'

    # Analyze recent behavior.
    look = min(n, 8)
    recent_opp = opp[-look:]
    recent_d = recent_opp.count('D')
    recent_c = look - recent_d

    # Strong recent defection: retaliate.
    if recent_d >= 4:
        if n % 5 == 0:
            return 'C'
        return 'D'

    # Moderate recent defection: mostly retaliate with some forgiveness.
    if recent_d >= 2:
        if last_opp == 'D':
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'C'

    # Opponent just defected against our cooperation: punish, but don't spiral.
    if last_opp == 'D' and last_me == 'C':
        # If we defected last round too many times recently, alternate back to C.
        if n >= 3 and me[-2] == 'D' and opp[-2] == 'D':
            return 'C'
        return 'D'

    # Opponent defected against our defection: try to restart cooperation.
    if last_opp == 'D' and last_me == 'D':
        if opp_d * 2 < n:
            return 'C'
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # Opponent cooperated after our defection: stay cooperative, occasionally test.
    if last_opp == 'C' and last_me == 'D':
        if coop_rate > 0.7 and n % 11 == 0 and remaining > 5:
            return 'D'
        return 'C'

    # Opponent is generally uncooperative overall: apply mild punishment.
    if coop_rate < 0.3:
        if rng.random() < 0.7:
            return 'D'
        return 'C'

    # Opponent mostly cooperative: cooperate, with rare probing.
    if coop_rate > 0.85:
        if n >= 15 and n % 13 == 0 and remaining > 10:
            return 'D'
        return 'C'

    # Moderate cooperation: cooperate by default, retaliate on last D.
    if last_opp == 'D':
        return 'D'
    # Occasional probing when cooperation seems stable.
    if n >= 20 and coop_rate > 0.6 and n % 17 == 0 and remaining > 8:
        return 'D'
    return 'C'
